import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Block overview","description":"The three block groups in ApptiveGrid pages and when you need which.","frontmatter":{"title":"Block overview","description":"The three block groups in ApptiveGrid pages and when you need which."},"headers":[],"relativePath":"en/seiten/bloecke.md","filePath":"en/seiten/bloecke.md","lastUpdated":1787319236000}'),i={name:"en/seiten/bloecke.md"};function n(s,t,l,d,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="block-overview" tabindex="-1">Block overview <a class="header-anchor" href="#block-overview" aria-label="Permalink to &quot;Block overview&quot;">​</a></h1><p>Blocks are the building blocks of a page. This page organizes them — the full list with all settings is in the <a href="/en/referenz/blocktypen">Block types reference</a>.</p><h2 id="the-three-groups" tabindex="-1">The three groups <a class="header-anchor" href="#the-three-groups" aria-label="Permalink to &quot;The three groups&quot;">​</a></h2><p>The block picker is organized into:</p><table tabindex="0"><thead><tr><th>Group</th><th>For</th></tr></thead><tbody><tr><td><strong>Basic Blocks</strong></td><td>Text, headings, images, sub-pages, layout</td></tr><tr><td><strong>Special Blocks</strong></td><td>Displaying, evaluating, embedding, and linking data</td></tr><tr><td><strong>Form field Blocks</strong></td><td>Collecting data</td></tr></tbody></table><h2 id="basic-blocks" tabindex="-1">Basic Blocks <a class="header-anchor" href="#basic-blocks" aria-label="Permalink to &quot;Basic Blocks&quot;">​</a></h2><p>The foundation of every page: <strong>Paragraph</strong>, <strong>Heading 1</strong> through <strong>3</strong>, <strong>Image</strong>, <strong>Page</strong> (sub-page), and the four Layout blocks.</p><p>With these you build documentation, manuals, and notes — and with the layouts, the structure for everything else.</p><p>→ <a href="/en/seiten/layout-bloecke">Layout blocks</a></p><h2 id="special-blocks" tabindex="-1">Special Blocks <a class="header-anchor" href="#special-blocks" aria-label="Permalink to &quot;Special Blocks&quot;">​</a></h2><p>This is where the real difference from a plain text document lies.</p><h3 id="displaying-data" tabindex="-1">Displaying data <a class="header-anchor" href="#displaying-data" aria-label="Permalink to &quot;Displaying data&quot;">​</a></h3><ul><li><strong>Grid View</strong> — embeds an existing view. The most important block for Portals.</li><li><strong>Grid List</strong> — turns entries into a freely designed list.</li><li><strong>File list</strong> — list view with drag-and-drop upload.</li></ul><h3 id="evaluating" tabindex="-1">Evaluating <a class="header-anchor" href="#evaluating" aria-label="Permalink to &quot;Evaluating&quot;">​</a></h3><ul><li><strong>Counter</strong> — number of entries in a view</li><li><strong>Sum card</strong> — sum of a numeric column</li><li><strong>Donut chart</strong> — distribution over a single-select column</li></ul><div class="tip custom-block"><p class="custom-block-title">A dashboard in five minutes</p><p>Three or four evaluation blocks in a horizontal layout make a metrics row. An embedded Grid view underneath with the details — that&#39;s usually all a decent dashboard needs.</p></div><h3 id="triggering-actions" tabindex="-1">Triggering actions <a class="header-anchor" href="#triggering-actions" aria-label="Permalink to &quot;Triggering actions&quot;">​</a></h3><ul><li><strong>Button</strong> — starts a form or a Flow</li><li><strong>QR code</strong> — the same, as a QR code, for posters and print</li><li><strong>Flow</strong> — embeds a Flow</li></ul><h3 id="embedding-external-content" tabindex="-1">Embedding external content <a class="header-anchor" href="#embedding-external-content" aria-label="Permalink to &quot;Embedding external content&quot;">​</a></h3><ul><li><strong>Embed</strong> — any external content via iframe</li><li><strong>HTML</strong> — your own code, optionally AI-generated</li></ul><h2 id="form-field-blocks" tabindex="-1">Form field Blocks <a class="header-anchor" href="#form-field-blocks" aria-label="Permalink to &quot;Form field Blocks&quot;">​</a></h2><p>All the input fields you know from <a href="/en/formulare/felder-konfigurieren">forms</a> — but here freely placeable, combinable with text and layout, and with <a href="/en/seiten/sichtbarkeit">conditional visibility</a>.</p><p>Roughly by purpose:</p><table tabindex="0"><thead><tr><th>Purpose</th><th>Blocks</th></tr></thead><tbody><tr><td>Text</td><td>Single-line text field, Multi-line text field</td></tr><tr><td>Numbers</td><td>Number, Decimal, Currency, Rating scale</td></tr><tr><td>Selection</td><td>Select as dropdown, Select as list, Multiple select, Checkmark, Decision</td></tr><tr><td>Time</td><td>Date, Date and time</td></tr><tr><td>Contact</td><td>Email, Phone, URL, Address</td></tr><tr><td>Location</td><td>Geolocation</td></tr><tr><td>Linking</td><td>Record, Records</td></tr><tr><td>Media</td><td>Upload files or photos, Photo camera, Video, Upload video, Voice recording</td></tr><tr><td>Other</td><td>Signature, Barcode scanner, HTML with form fields</td></tr></tbody></table><h2 id="which-block-for-which-task" tabindex="-1">Which block for which task <a class="header-anchor" href="#which-block-for-which-task" aria-label="Permalink to &quot;Which block for which task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to …</th><th>Block</th></tr></thead><tbody><tr><td>Show a table in the Portal</td><td><strong>Grid View</strong></td></tr><tr><td>Highlight a single metric</td><td><strong>Counter</strong> or <strong>Sum card</strong></td></tr><tr><td>Show a distribution</td><td><strong>Donut chart</strong></td></tr><tr><td>Let visitors start a process</td><td><strong>Button</strong></td></tr><tr><td>Make something scannable on a poster</td><td><strong>QR code</strong></td></tr><tr><td>Collect files</td><td><strong>File list</strong> or <strong>Upload files or photos</strong></td></tr><tr><td>Repeat content per entry</td><td><strong>Grid List</strong></td></tr><tr><td>Show something external</td><td><strong>Embed</strong></td></tr><tr><td>Full design freedom</td><td><strong>HTML</strong></td></tr><tr><td>Multiple areas on one page</td><td><strong>Tab layout</strong></td></tr><tr><td>A guided process</td><td><strong>Stepper layout</strong></td></tr></tbody></table><h2 id="nesting-blocks" tabindex="-1">Nesting blocks <a class="header-anchor" href="#nesting-blocks" aria-label="Permalink to &quot;Nesting blocks&quot;">​</a></h2><p>Layout blocks contain other blocks. Two metrics side by side with a table below is built like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vertical layout</span></span>
<span class="line"><span>├── Horizontal layout</span></span>
<span class="line"><span>│   ├── Counter</span></span>
<span class="line"><span>│   └── Sum card</span></span>
<span class="line"><span>└── Grid View</span></span></code></pre></div><p>At this level of nesting, you should work in <a href="/en/seiten/seite-erstellen">structure mode</a> — in the regular editor it&#39;s hard to tell which block sits inside which.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/referenz/blocktypen">Block types reference</a></li><li><a href="/en/seiten/layout-bloecke">Layout blocks</a></li><li><a href="/en/seiten/auswertungen">Embedding views and evaluations</a></li><li><a href="/en/seiten/sichtbarkeit">Conditional visibility</a></li></ul>`,32)])])}const p=e(i,[["render",n]]);export{u as __pageData,p as default};
